package storage

import (
	"crypto/sha1"
	"encoding/hex"
	"fmt"
	"io"
)

// Object 타입 정의
type ObjectType string

const (
	BlobType   ObjectType = "blob"
	TreeType   ObjectType = "tree"
	CommitType ObjectType = "commit"
)

// Object는 FreeGit의 기본 불변 데이터 단위
type Object struct {
	Type    ObjectType // blob, tree, commit
	Content []byte     // 실제 데이터
	Hash    string     // SHA1 해시값
}

// NewBlob은 파일 내용으로부터 Blob 객체를 생성합니다.
// 내용만으로 객체를 식별하므로, 동일한 내용은 항상 같은 해시값을 가집니다.
func NewBlob(content []byte) *Object {
	return &Object{
		Type:    BlobType,
		Content: content,
		Hash:    calculateHash(BlobType, content),
	}
}

// calculateHash는 FreeGit 방식의 해시값을 계산합니다.
// 형식: SHA1(type + space + size + null_byte + content)
// 예: "blob 11\x00Hello World" → SHA1 → "a7cf..."
func calculateHash(objType ObjectType, content []byte) string {
	// 1. 헤더 생성: "blob 11\x00"
	header := fmt.Sprintf("%s %d\x00", objType, len(content))

	// 2. 전체 데이터: 헤더 + 내용
	fullData := append([]byte(header), content...)

	// 3. SHA1 계산
	hash := sha1.Sum(fullData)

	// 4. 16진수 문자열로 변환
	return hex.EncodeToString(hash[:])
}

// Hash 메서드는 객체의 해시값을 반환합니다.
func (o *Object) Hash_() string {
	return o.Hash
}

// Size는 객체의 크기를 반환합니다.
func (o *Object) Size() int {
	return len(o.Content)
}

// Serialize는 객체를 저장 가능한 형식으로 직렬화합니다.
// (헤더 + 내용의 원본 형태)
func (o *Object) Serialize() []byte {
	header := fmt.Sprintf("%s %d\x00", o.Type, len(o.Content))
	return append([]byte(header), o.Content...)
}

// Deserialize는 저장된 바이트로부터 객체를 복원합니다.
func Deserialize(data []byte) (*Object, error) {
	// null byte를 기준으로 헤더와 내용 분리
	var objType ObjectType
	var size int
	headerEnd := -1

	for i := 0; i < len(data); i++ {
		if data[i] == '\x00' {
			headerEnd = i
			break
		}
	}

	if headerEnd == -1 {
		return nil, fmt.Errorf("invalid object format: missing null byte")
	}

	// 헤더 파싱
	headerStr := string(data[:headerEnd])
	_, err := fmt.Sscanf(headerStr, "%s %d", &objType, &size)
	if err != nil {
		return nil, fmt.Errorf("invalid header format: %w", err)
	}

	// 내용 추출
	content := data[headerEnd+1:]
	if len(content) != size {
		return nil, fmt.Errorf("content size mismatch: expected %d, got %d", size, len(content))
	}

	obj := &Object{
		Type:    objType,
		Content: content,
		Hash:    calculateHash(objType, content),
	}

	return obj, nil
}

// DeserializeReader는 io.Reader로부터 객체를 복원합니다.
func DeserializeReader(r io.Reader) (*Object, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, fmt.Errorf("failed to read data: %w", err)
	}
	return Deserialize(data)
}

