# ================================================================

fn parseArgs(args: [string]): map {
  if len(args) == 0 {
    return { "mode": "repl" }
  } else if len(args) >= 1 {
    let cmd = args[0]

    if cmd == "--eval" and len(args) >= 2 {
      return {
        "mode": "eval",
        "code": args[1]
      }
    } else {
      return {
        "mode": "file",
        "filename": cmd
      }
    }
  } else {
    return { "mode": "repl" }
  }
}

# ================================================================
