  if len(args) == 0 {
    return { "command": "help" }
  }

  let cmd = args[0]

  if cmd == "init" {
    return {
      "command": "init",
      "path": if len(args) > 1 then args[1] else "."
    }
  } else if cmd == "add" {
    return {
