fn parseCommand(args: [string]): map {
  if len(args) == 0 {
    return { "command": "help" }
  }

  let cmd = args[0]

  if cmd == "init" {
    return {
      "command": "init",
      "path": if len(args) > 1 then args[1] else "."
    }
  } else if cmd == "add" {
    return {
      "command": "add",
      "files": slice(args, 1, len(args))
    }
  } else if cmd == "commit" {
    return {
      "command": "commit",
      "message": if len(args) > 1 then args[1] else "",
      "author": if len(args) > 2 then args[2] else "Unknown"
    }
  } else if cmd == "log" {
    return {
      "command": "log",
      "maxCount": if len(args) > 1 then parseInt(args[1]) else 10
    }
  } else if cmd == "fsck" {
    return { "command": "fsck" }
  } else if cmd == "cat-file" {
    return {
      "command": "cat-file",
      "hash": if len(args) > 1 then args[1] else ""
    }
  } else if cmd == "status" {
    return { "command": "status" }
  } else {
    return { "command": "help" }
  }
}

# ================================================================
# Part 2: 커맨드 실행
# ================================================================

fn executeCommand(parsedCmd: map): i32 {
  let command = parsedCmd["command"]

  if command == "init" {
    return cmdInit(parsedCmd["path"])
  } else if command == "add" {
    return cmdAdd(parsedCmd["files"])
  } else if command == "commit" {
    return cmdCommit(parsedCmd["message"], parsedCmd["author"])
  } else if command == "log" {
    return cmdLog(parsedCmd["maxCount"])
  } else if command == "fsck" {
    return cmdFsck()
  } else if command == "cat-file" {
    return cmdCatFile(parsedCmd["hash"])
  } else if command == "status" {
    return cmdStatus()
  } else {
    return cmdHelp()
  }
}

