  let blob2 = createBlob(content2)

  # 해시값이 동일한지 확인
  if blob1["hash"] != blob2["hash"] {
    println("❌ Deduplication failed: different hashes for same content")
    return false
  }

  println("✅ Deduplication passed: same content = same hash")
  return true
}

