# ================================================================

fn testHashUniqueness(): bool {
  let content1 = createTestBytes("Content A")
  let blob1 = createBlob(content1)

  let content2 = createTestBytes("Content B")
  let blob2 = createBlob(content2)

  if blob1["hash"] == blob2["hash"] {
    println("❌ Hash uniqueness failed: different content same hash")
    return false
  }

  println("✅ Hash uniqueness passed: different content = different hash")
  return true
}

