# ================================================================
# FreeGit 2단계: Tree 엔진 (폴더 구조 기록)
# 여러 파일과 폴더를 하나의 객체로 관리
# ================================================================

# ================================================================
# Part 1: Tree 엔트리 정의
# ================================================================

# Tree 엔트리 생성
fn createTreeEntry(mode: string, objectType: string, hash: string, name: string): map {
  return {
    "mode": mode,
    "type": objectType,
    "hash": hash,
    "name": name
  }
}

# Tree 엔트리 직렬화 (저장 형식)
fn serializeTreeEntry(entry: map): string {
  # 형식: "mode type hash\tname\n"
  # 예: "100644 blob a1b2c3...\tfile.txt\n"

  let mode = entry["mode"]
  let entryType = entry["type"]
  let hash = entry["hash"]
  let name = entry["name"]

  return mode + " " + entryType + " " + hash + "\t" + name + "\n"
}

# ================================================================
# Part 2: Tree 객체 생성
# ================================================================

# Tree 생성 (엔트리 목록으로부터)
fn createTree(entries: [map]): map {
  # 1. 엔트리들을 정렬 (Git은 이름순 정렬)
  let sortedEntries = sortTreeEntries(entries)

  # 2. 엔트리를 직렬화
  let treeData = ""
  for entry in sortedEntries {
    treeData = treeData + serializeTreeEntry(entry)
  }

  # 3. Tree 객체의 헤더 추가
  # "tree {size}\x00{data}"
  let size = len(treeData)
  let header = "tree " + toString(size) + "\x00"
  let fullData = header + treeData

  # 4. 전체 데이터를 해싱
  let hash = calculateTreeHash(fullData)

  return {
    "type": "tree",
    "entries": sortedEntries,
    "data": treeData,
    "size": size,
    "hash": hash
  }
}

# Tree 해시 계산
fn calculateTreeHash(data: string): string {
  return simpleHash(data)
}

# ================================================================
# Part 3: 폴더 스캔 (재귀)
# ================================================================

# 디렉토리로부터 자동으로 Tree 생성
fn createTreeFromDirectory(dirPath: string, repoPath: string): map {
  let entries = [] as [map]

  # 1. 디렉토리 내 파일 목록 스캔
  let items = listDirectory(dirPath)

  # 2. 각 항목 처리
  for item in items {
    # .freegit 디렉토리는 제외
    if item == ".freegit" {
      continue
    }

    let itemPath = dirPath + "/" + item
    let isDir = isDirectory(itemPath)

    if isDir {
      # 3-1. 폴더면 재귀적으로 Tree 생성
      let subTree = createTreeFromDirectory(itemPath, repoPath)
      let entry = createTreeEntry("040000", "tree", subTree["hash"], item)
      entries = append(entries, entry)

      # 저장소에 저장
      storeTree(repoPath, subTree)
    } else {
      # 3-2. 파일이면 Blob 생성
      let content = readFile(itemPath)
      let blob = createBlob(content)
      let entry = createTreeEntry("100644", "blob", blob["hash"], item)
      entries = append(entries, entry)

      # 저장소에 저장
      storeBlob(repoPath, blob)
    }
  }

  # 4. Tree 생성 및 반환
  return createTree(entries)
}

