fn storeTree(repoPath: string, tree: map): bool {
  let hash = tree["hash"]
  let data = tree["data"]

  # 저장 경로: .freegit/objects/xx/yyyyyyyy
  let dirPart = substr(hash, 0, 2)
  let filePart = substr(hash, 2, 38)
  let filePath = repoPath + "/.freegit/objects/" + dirPart + "/" + filePart

  # 헤더 포함하여 저장
  let header = "tree " + toString(tree["size"]) + "\x00"
  let fullData = header + data

  writeFile(filePath, fullData)
  return true
}

# Tree 읽기
fn readTree(repoPath: string, hash: string): map {
  let dirPart = substr(hash, 0, 2)
  let filePart = substr(hash, 2, 38)
  let filePath = repoPath + "/.freegit/objects/" + dirPart + "/" + filePart

  let content = readFile(filePath)

  # "tree {size}\x00{data}" 형식에서 데이터만 추출
  # TODO: 파싱 구현

  return {
    "type": "tree",
    "hash": hash,
    "data": content
  }
}

# ================================================================
# Part 5: 검증 (무결성 확인)
# ================================================================

# Tree 검증
fn verifyTree(repoPath: string, hash: string): bool {
  let tree = readTree(repoPath, hash)
  let recalculatedHash = calculateTreeHash(tree["data"])

  return recalculatedHash == hash
}

# Merkle Tree 검증 (재귀적)
fn verifyTreeRecursive(repoPath: string, hash: string): bool {
  # Tree 자신의 무결성 확인
  if !verifyTree(repoPath, hash) {
    return false
  }

  # 각 엔트리의 하위 객체도 검증
